command:
$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-17 (retry, narrowed). Closes CONT-997-SECONDARY-OWNER-CANDIDATES-LISTED-NOT-READ,
# raised by the independent review of report 001 and assigned to THIS lane "BEFORE any reconciliation
# is written". It was not done before; it is being done now, and the report says so in those words.
#
# The question: report 001 proved the live ollama container carried no compose labels and was created
# by hand on 2026-08-18, so something outside compose made it. If that something is a script still
# present that issues a direct `docker run`, then removing the container and the compose stanza gives
# one owner only until somebody runs that script -- and this lane's central claim would be overstated.
#
# The first attempt timed out recursing C:\HermesLab, which contains a full release-staging checkout.
# Narrowed to the directory the finding actually names, plus the two other places a container
# definition could plausibly live. Scope stated rather than silently reduced.

Write-Output '--- CANDIDATES IN C:\HermesLab\hermes ---'
$files = Get-ChildItem 'C:\HermesLab\hermes' -File -ErrorAction SilentlyContinue |
    Where-Object { $_.Extension -in '.ps1', '.cmd', '.bat', '.sh', '.reg', '.yml', '.yaml' }
Write-Output "candidate_count=$($files.Count)"
Write-Output "candidates=$(($files.Name | Sort-Object) -join ', ')"

Write-Output ''
Write-Output '--- EVERY CANDIDATE READ; CONTAINER-CREATING OR OLLAMA-TOUCHING LINES ---'
$directRun = @()
foreach ($f in ($files | Sort-Object Name)) {
    $lines = Get-Content $f.FullName -ErrorAction SilentlyContinue
    if ($null -eq $lines) { Write-Output "  FILE $($f.Name) :: UNREADABLE"; continue }
    $hits = @()
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match 'docker\s+(run|create|start|compose)|docker-compose|ollama|11434') {
            $hits += "      L$($i + 1): $($lines[$i].Trim())"
        }
    }
    if ($lines -match 'docker\s+run' -or $lines -match 'docker\s+create') { $directRun += $f.Name }
    if ($hits.Count -gt 0) {
        Write-Output "  FILE $($f.Name)  sha256=$((Get-FileHash $f.FullName -Algorithm SHA256).Hash.ToLower().Substring(0,16))"
        $hits | Select-Object -First 12 | ForEach-Object { Write-Output $_ }
        if ($hits.Count -gt 12) { Write-Output "      ... $($hits.Count - 12) more matching lines" }
    } else {
        Write-Output "  FILE $($f.Name)  read, no docker/ollama/11434 reference"
    }
}

Write-Output ''
Write-Output '--- VERDICT ---'
Write-Output "files_issuing_docker_run_or_create=$(if ($directRun) { ($directRun | Sort-Object -Unique) -join ',' } else { 'NONE' })"

Write-Output ''
Write-Output '--- THE OTHER COMPOSE PROJECT ON THIS BOX ---'
$p = 'D:\HermesServices\williamos-hermes-agent\compose.yaml'
Write-Output "$p exists=$(Test-Path $p)"
if (Test-Path $p) {
    Write-Output "  sha256=$((Get-FileHash $p -Algorithm SHA256).Hash.ToLower())"
    $c = Get-Content $p -ErrorAction SilentlyContinue
    for ($i = 0; $i -lt $c.Count; $i++) {
        if ($c[$i] -match 'ollama|11434|image:|container_name:|services:') { "      L$($i + 1): $($c[$i].Trim())" }
    }
}
Write-Output '  every container docker knows about, and which config file owns it:'
docker ps -a --format '{{.Names}}|{{.Label "com.docker.compose.project.config_files"}}' 2>&1

Write-Output ''
Write-Output '--- STARTUP REG BACKUP ---'
Get-Content 'C:\HermesLab\hermes\startup-run-backup.reg' -ErrorAction SilentlyContinue | Select-Object -First 25

Write-Output ''
Write-Output '--- AUDIT LEDGER: WHAT THIS LANE ACTUALLY RECORDED ---'
# `--require-audit` is inert against this broker (b9f5138b... has no requireAudit / requireLedger at
# all), so the honest claim is not "the ledger was proven writable before the node was touched" but
# "the calls went through brokeredExec and were appended". Check that the appends are really there.
$ledger = 'C:\Users\bs\.williamos\fabric\audit.log'
Write-Output "ledger=$ledger exists=$(Test-Path $ledger)"
if (Test-Path $ledger) {
    Write-Output "ledger_lines=$((Get-Content $ledger | Measure-Object -Line).Lines)"
    Write-Output "entries containing 'mig-': $((Get-Content $ledger | Select-String -Pattern 'mig-' | Measure-Object).Count)"
    Get-Content $ledger -Tail 40 | ForEach-Object { "  $_" }
}
Write-Output '--- RC ---'
